def doubling_orbits():
    """TICK_CYCLE, OBS_FALLS, NAKSHATRA_SPLIT and THREE_DOUBLES: what doubling does to each clock."""
    def cycle_lengths(points, step):
        seen, lengths = set(), []
        for s in points:
            if s in seen:
                continue
            n, y = 0, s
            while y not in seen:
                seen.add(y)
                y, n = step(y), n + 1
            lengths.append(n)
        return sorted(lengths)
