    bargmann = max(abs(np.vdot(a, b) * np.vdot(b, c) * np.vdot(c, a)) for a, b, c in ((unit(), unit(), unit()) for _ in range(500)))
    B = sp.Matrix([[1, 1], [1, 0]])
