    phi = sp.Matrix([((A ** 2 + B ** 2) * A).trace() / 6, ((A ** 2 + B ** 2) * B).trace() / 6]).applyfunc(sp.expand)
    Ja, Jb = phi.jacobian(list(av)), phi.jacobian(list(bv))
    at = lambda a, b: dict(zip(list(av) + list(bv), list(a) + list(b)))

