def _connected_nonbipartite(edges):
    """True if the graph on the five vertices with these edges is connected and not bipartite."""
    adj = {v: [] for v in range(5)}
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    col, stack, odd = {0: 0}, [0], False
    while stack:
        v = stack.pop()
        for w in adj[v]:
            if w not in col:
                col[w] = 1 - col[v]
                stack.append(w)
            elif col[w] == col[v]:
                odd = True
    return len(col) == 5 and odd


