    Q = 10 * np.ones((6, 6), dtype=np.int64) - 4 * np.eye(6, dtype=np.int64)
    spec = Counter(int(round(x)) for x in np.linalg.eigvalsh(A.astype(float)))
    finite = [int(np.trace(np.linalg.matrix_power(A, k))) // 240 for k in range(5)]
