    invs = [next(j for j in range(nU) if table[i][j] == e) for i in range(nU)]
    M240 = U + [qscal(PHI_INV, u) for u in U]
    G240 = np.array([[ip2(p, q) for q in M240] for p in M240], dtype=np.int64) // 2
    B_, Binv_, C, Cinv, R, RB = spine.frame()
