    PB = np.einsum("hk,tkx->thx", C5[:, 4:], R2[Ch])
    code = lambda Y: ((Y + 2) * (5 ** np.arange(8))).sum(-1)
    inH = np.zeros(5 ** 8, dtype=bool)
    inH[code(R2[H])] = True
    where = np.full(5 ** 8, -1)
    where[code(R2[H])] = np.arange(len(H))
