    ints = R2[np.all(R2 % 2 == 0, axis=1)] // 2                                 # the integer roots
    half = R2[np.all(R2 % 2 != 0, axis=1)]                                      # the half-integer roots, doubled

    def dn(m):
        Im = np.eye(m, dtype=np.int64)
        return np.array([s * Im[i] + u * Im[j] for i, j in itertools.combinations(range(m), 2)
                         for s in (1, -1) for u in (1, -1)])

    def psum(V, k, den=1):
        """sum over v of (v.h / den)^k, coefficient by coefficient (exponent tuple -> Fraction)."""
        V = np.asarray(V, dtype=np.int64)
        out = {}
        for cmb in itertools.combinations_with_replacement(range(V.shape[1]), k):
            m = tuple(np.bincount(np.array(cmb), minlength=V.shape[1]).tolist())
            tot = int(np.prod(V ** np.array(m), axis=1).sum())
            if tot:
                out[m] = Fraction(factorial(k) * tot, int(np.prod([factorial(a) for a in m])) * den ** k)
        return out

    def pdict(expr, hs):
        return {m: Fraction(int(sp.numer(c)), int(sp.denom(c)))
                for m, c in sp.Poly(sp.expand(expr), *hs).as_dict().items() if c != 0}

    def add(a, b):
        out = Counter(a)
        for m, c in b.items():
            out[m] += c
        return {m: c for m, c in out.items() if c != 0}

