    KD = sp.Matrix.hstack(*Wm.nullspace())
    PiD = KD * (KD.T * G2 * KD).inv() * KD.T * G2
    W2 = lambda p: compound2(rho(p))
    dchi = [(W2(p) * PiD).trace() for p in allS5]
    # intertwiners X: ker M -> dark four, X = vec^-1: sg W2(g) X = X rho(g) and (I - Pi_D) X = 0
    from sympy.polys.matrices import DomainMatrix
    rk = lambda A: DomainMatrix.from_Matrix(A).convert_to(sp.QQ).rank()
    kron = lambda A, B: sp.Matrix(A.rows * B.rows, A.cols * B.cols,
                                  lambda i, j: A[i // B.rows, j // B.cols] * B[i % B.rows, j % B.cols])

    def hom_dim(gens):
        rows = [kron(sp.eye(5), sg * W2(g)) - kron(rho(g).T, sp.eye(10)) for g, sg in gens]
        return 50 - rk(sp.Matrix.vstack(*rows, kron(sp.eye(5), sp.eye(10) - PiD)))
    hom = [hom_dim(gs) for gs in ([(rot, 1)], [(rot, 1), (ref, 1)], [(rot, 1), (ref, 1), (dbl, -1)],
                                  [(rot, 1), (ref, 1), (dbl, 1)])]
