    el = {(p, y): key(mp(g, p) @ mp(Ur, y)) for p in range(5) for y in range(5)}
    img = Counter(el[(4 * j) % 5, y] for j in range(N) for y in range(5))
    fib1 = [(j, y) for j in range(N) for y in range(5) if el[(4 * j) % 5, y] == key(I8)]
    # joint characters of <r> x <r'>: principal angle of a in Z/5 (units of pi) and the winding pairs
