    tr8 = {(j, k): int(np.trace(mp(r, j) @ mp(rp, k))) for j in range(5) for k in range(5)}
    B_, Binv, C_, Cinv, R_, RB = spine.frame()
    fixr = {(j, k): sum(1 for v in RB if np.array_equal(mp(r, j) @ mp(rp, k) @ v, v)) for j in range(5) for k in range(5)}

    def mixed(T):
        """(T00 - T10 - T01 + T11)/25: the multiplicity of each joint character (a, b), a, b != 0, when the trace
        T(j, k) depends only on whether j and k vanish."""
        ok = all(T[j, k] == T[int(j != 0), int(k != 0)] for j in range(5) for k in range(5))
        return ok, sp.Rational(T[0, 0] - T[1, 0] - T[0, 1] + T[1, 1], 25)
    tensor = {(j, k): tr8[j, 0] * tr8[0, k] for j in range(5) for k in range(5)}
    # R^8 = V_A + V_A' with V_A = ran(r - 1) (where r' is 1) and V_A' = ran(r' - 1): the mixed sixteen V_A (x) V_A'
    rkA, rkB, rkAB = (sp.Matrix(X_.tolist()).rank() for X_ in (r - I8, rp - I8, np.hstack([r - I8, rp - I8])))
    mix16 = {(j, k): (tr8[j, 0] - 4) * (tr8[0, k] - 4) for j in range(5) for k in range(5)}
    # the wave-memory defect on a generic symmetric K (4 x 4) with the isometry Y = [I2; 0]
    kk = sp.symbols("k0:10", real=True)
    K = sp.zeros(4)
    for v, (i, j) in zip(kk, [(i, j) for i in range(4) for j in range(i, 4)]):
        K[i, j] = K[j, i] = v
    Y = sp.Matrix.vstack(sp.eye(2), sp.zeros(2, 2))
    Q = sp.eye(4) - Y * Y.T
    Kp = [sp.eye(4)]
    for _ in range(4):
        Kp.append((Kp[-1] * K).applyfunc(sp.expand))
    cosn = lambda n, sc: (-1) ** n * sc ** n * Kp[n] / sp.factorial(2 * n)        # u^(2n) coefficient of cos(u sqrt(sc K))
    CY = [Y.T * cosn(n, 1) * Y for n in range(5)]
