    lhs = upto((1 + Cs(2 * u)) / 2 - Cs(u) * Cs(u), u, 10)
    rhs = upto(sum(cf(m) * cf(n) * u ** (2 * (m + n)) * (An[m + n] - An[m] * An[n])
                   for m in range(6) for n in range(6) if m + n <= 5), u, 10)
    Fu = sum(((-sp.I * th) ** n / sp.factorial(n) * An[n] for n in range(7)), sp.Integer(0))
    Fs = sum(((sp.I * th) ** n / sp.factorial(n) * An[n] for n in range(7)), sp.Integer(0))
    lhs1 = upto(1 - Fs * Fu, th, 6)
