    H = (sum((J * Zs[i] * Zs[j] for (i, j), J in Jij.items()), sp.zeros(8, 8)) + sum((h * Z for h, Z in zip(hs, Zs)), sp.zeros(8, 8))
         + J3 * Zs[0] * Zs[1] * Zs[2] + Om / 2 * sum(Xs, sp.zeros(8, 8)))
