        cs = [sp.Rational(1, s) / (z + m) ** power for s, m in zip(sc, mu)]
        dd = int(sp.ilcm(*[sp.fraction(x)[1] for x in cs]))
        return sum((int(x * dd) * P.astype(object) for x, P in zip(cs, Pint)), np.zeros((240, 240), dtype=object)), dd
