    H0 = sp.Matrix(sp.BlockMatrix([[A0, Bt], [Bt, C0]]))
    F = sp.diag(0, 2, 3)
    Ce = C0 + eps * sp.eye(3)
    V = F + Bt * Ce.inv() * Bt - A0 - eps * sp.eye(3)
    J = sp.Matrix.vstack(sp.eye(3), sp.zeros(3, 3))
    K = H0 + eps * sp.eye(6) + J * V * J.T
