def bind_time_units():
    """The units-correct two-step binding (the Drive audit T1-T5, 6 Nov, read as data): a load's inverse-response shift
    is exact (master_response's S_K^-1 - S_H^-1 = V; tdc_frequency's clock-scaled law), so a measured shift d in s^-2
    gives tau^2 = delta_model/d in the kappa = 1 gauge, and kappa = tau^2/rho^2 with rho from bind_time_map is then the
    gauge consistency kappa = 1, tau = rho (video_ten_fisher): the shift is gauge-invariant, (delta/rho^2) e e^T, so it
    fixes rho only, as the three-route note's d = 8/rho^2 says, and d^2/Xi_q = delta^2/389 is a rho-free relation. The
    dimension check uses sympy.physics.units and a plain exponent count."""
    from sympy.physics.units import newton, meter, second, kilogram, convert_to
    s, tau, delta, rho, kappa, d = sp.symbols("s tau delta rho kappa d", positive=True)
    K = sp.Matrix(2, 2, lambda i, j: sp.Symbol("k%d%d" % (min(i, j), max(i, j)), real=True))
    e = sp.Matrix([1, 0])
    R0 = (s ** 2 * sp.eye(2) + K / tau ** 2).inv()
    RL = (s ** 2 * sp.eye(2) + (K + delta * e * e.T) / tau ** 2).inv()
    shift = sp.simplify(RL.inv() - R0.inv() - (delta / tau ** 2) * e * e.T)
    tau2 = sp.solve(sp.Eq(d, delta / tau ** 2), tau ** 2)
    kap = sp.solve(sp.Eq(rho, tau / sp.sqrt(kappa)), kappa)
    units = convert_to((newton / meter) / (1 / second ** 2), kilogram)
    units2 = convert_to(sp.Integer(1) / (1 / second ** 2), second ** 2)
    exp_stiff, exp_d, exp_one = (1, 0, -2), (0, 0, -2), (0, 0, 0)                 # (M, L, T) exponents
    quot = tuple(a - b for a, b in zip(exp_stiff, exp_d))
    quot2 = tuple(a - b for a, b in zip(exp_one, exp_d))
    RLk = (s ** 2 * sp.eye(2) + (kappa / tau ** 2) * (K + delta * e * e.T)).inv()
    R0k = (s ** 2 * sp.eye(2) + (kappa / tau ** 2) * K).inv()
    shift_k = sp.simplify(RLk.inv() - R0k.inv() - (kappa * delta / tau ** 2) * e * e.T)
    d_inv = sp.simplify((kappa * delta / tau ** 2).subs(tau, rho * sp.sqrt(kappa)) - delta / rho ** 2)   # d = delta/rho^2
    Xq = 389 / rho ** 4                                                         # Xi_q = 389/rho^4 (bind_time_map)
    ratio = sp.simplify((delta / rho ** 2) ** 2 / Xq - delta ** 2 / 389)
    gap8 = (sp.Integer(8) ** 2 / 389, Fraction(64, 389))
    lam_minus = (5 - sp.sqrt(5)) / 2
    return {
        "the load shift is gauge-invariant and fixes rho only: for the gauge-covariant generator (kappa/tau^2) (K + "
        "delta e e^T) the inverse-response shift is (kappa delta/tau^2) e e^T = (delta/rho^2) e e^T (symbolic on a "
        "generic 2 x 2 K), so a measured d (s^-2) reads rho^2 = delta/d, unchanged by (c tau, c^2 kappa), as the "
        "three-route note's d = 8/rho^2 says, and never tau and kappa apart; with Xi_q = 389/rho^4 the ratio d^2/Xi_q "
        "= delta^2/389 is a fourth rho-free relation, 64/389 at the note's static gap delta = 8 (the receipt's "
        "d_squared_over_vq_if_static_gap_is_8, read as data; 'to be tested, not used to define rho'); that gap is the "
        "note's stiffness-eight branch, not the model's dressed gap: deep_zero_pole's floor is min(alpha lam-, 8) with "
        "lam- = (5 - sqrt5)/2 in (1.3819, 1.3820) (chiral_closures' factors), the gap at alpha = 1 (zero_pole_instance)":
            shift_k == sp.zeros(2, 2) and d_inv == 0 and ratio == 0
            and gap8 == (sp.Rational(64, 389), Fraction(64, 389))
            and sp.Rational(13819, 10000) < lam_minus < sp.Rational(13820, 10000) and lam_minus < 8,
        "the load shift is exact and frequency-free: for R(s) = (s^2 I + tau^-2 (K + delta e e^T))^-1 on a generic "
        "symmetric 2 x 2 K, R_L(s)^-1 - R_0(s)^-1 = (delta/tau^2) e e^T at every s (master_response's S_K^-1 - S_H^-1 = "
        "V, tdc_frequency's clock-scaled law)":
            shift == sp.zeros(2, 2),
        "the two steps in the kappa = 1 gauge (the T1-T5 audit's generator tau^-2 (K + delta_model e e^T)): step one, "
        "the measured shift d := delta_model/tau^2 (in s^-2) gives tau^2 = delta_model/d; step two, kappa = tau^2/rho^2 "
        "from rho = tau/sqrt(kappa) with rho from bind_time_map, which in this gauge is the consistency kappa = 1, tau = "
        "rho = sqrt(delta_model/d): the steps are time first (rho) then the load (a gauge choice), and tau, kappa apart "
        "stay unidentified (refclock_calibration)":
            tau2 == [delta / d] and kap == [tau ** 2 / rho ** 2]
            and sp.simplify((tau / sp.sqrt(kappa)).subs({kappa: 1, tau: rho}) - rho) == 0
            and sp.simplify(kap[0].subs(tau ** 2, tau2[0]).subs(d, delta / rho ** 2)) == 1,
        "the dimensional statement: a dimensionless delta_model over d (s^-2) is s^2, tau^2's unit, while a stiffness "
        "step in N/m over d (s^-2) is a mass, kg, not a time squared (sympy.physics.units and the (M, L, T) exponents "
        "(1, 0, -2) - (0, 0, -2) = (1, 0, 0))":
            units == kilogram and units2 == second ** 2 and quot == (1, 0, 0) and quot2 == (0, 0, 2),
    }


def bind_dynamics_dyadic():
    """The Drive note P01 (TIME DYN P01-P20, 6 Nov 08:06), read as data, replayed: for Sigma(z) = B (z + C)^-1 B^T with
    C >= 0 and e(z) = [Sigma(z) - Sigma(4z)]/(3z), the dyadic partial sums Sigma_N(z) = 3z sum_(j < N) 4^j e(4^j z)
    leave the exact tail Sigma(4^N z), bounded in Loewner order by B B^T/(4^N z). Symbolic on a generic block and
    exact on master_response's root-site instance (15 bond atoms visible, 225 roots hidden, through its own block
    trick, _bind_rootsite); the load identity is master_response's source law (tdc_frequency cites it); the measured
    secant needs rho from bind_time_map, so the two bindings chain: time first, then dynamics. The separate model's
    three-route note and txt (6 Nov 08:44, read as data) add the scale-free form at x = s/s* and the one-anchor
    recovery, both replayed symbolically here."""
    z, s, rho = sp.symbols("z s rho", positive=True)
    Bs = sp.Matrix(2, 2, sp.symbols("b11 b12 b21 b22", real=True))
    Cs = sp.Matrix(2, 2, lambda i, j: sp.Symbol("c%d%d" % (min(i, j), max(i, j)), real=True))
    Ks = sp.Matrix(2, 2, lambda i, j: sp.Symbol("k%d%d" % (min(i, j), max(i, j)), real=True))
    Ls = sp.Matrix(2, 2, lambda i, j: sp.Symbol("l%d%d" % (min(i, j), max(i, j)), real=True))
    Sig = lambda w, Bm=Bs, Cm=Cs: Bm * (w * sp.eye(2) + Cm).inv() * Bm.T
    e_of = lambda w, Bm=Bs, Cm=Cs: (Sig(w, Bm, Cm) - Sig(4 * w, Bm, Cm)) / (3 * w)
    SigN = lambda N, w: 3 * w * sum((4 ** j * e_of(4 ** j * w) for j in range(N)), sp.zeros(2, 2))
    tails = [sp.simplify(Sig(z) - SigN(N, z) - Sig(4 ** N * z)) == sp.zeros(2, 2) for N in (1, 2, 3)]
    load = sp.simplify((z * sp.eye(2) + Ks + Ls).inv().inv() - (z * sp.eye(2) + Ks).inv().inv() - Ls) == sp.zeros(2, 2)
    # the measured secant under the physical normalization (B/rho, C/rho^2) and under the full generator K/rho^2
    E1 = sp.simplify(e_of(s ** 2, Bs / rho, Cs / rho ** 2) - rho ** 2 * e_of(rho ** 2 * s ** 2)) == sp.zeros(2, 2)
    E2 = sp.simplify(e_of(s ** 2, Bs / rho ** 2, Cs / rho ** 2) - e_of(rho ** 2 * s ** 2)) == sp.zeros(2, 2)
    needs_rho = rho in e_of(s ** 2, Bs / rho, Cs / rho ** 2).free_symbols
    # the scale-free form (the three-route note, 6 Nov 08:44, section 4): with the generator K/rho^2, E_phys(s) =
    # e((rho s)^2); at x = s/s* with rho s* = sqrt(z*) the dyadic sum reads Sigma in model units from rate ratios alone
    zs, x = sp.symbols("z_star x", positive=True)
    E_phys = lambda w: e_of(w ** 2, Bs / rho ** 2, Cs / rho ** 2)
    s_star = sp.sqrt(zs) / rho
    bands_free = [(E_phys(2 ** n * s_star * x) - e_of(4 ** n * zs * x ** 2)).applyfunc(sp.cancel) == sp.zeros(2, 2)
                  for n in (0, 1)]                                               # E_phys(2^n s* x) = e(4^n z* x^2), rho-free
    scale_free = 3 * zs * x ** 2 * sum((4 ** n * e_of(4 ** n * zs * x ** 2) for n in range(2)), sp.zeros(2, 2))
    sf_ok = all(bands_free) and (scale_free - (Sig(zs * x ** 2) - Sig(16 * zs * x ** 2))).applyfunc(sp.cancel) == sp.zeros(2, 2)
    sf_free = rho not in scale_free.free_symbols
    # the one-anchor recovery (the three-route txt, section 2): A from one full G(z0), then G(z)^-1 for every z
    z0 = sp.Symbol("z0", positive=True)
    As = sp.Matrix(2, 2, lambda i, j: sp.Symbol("a%d%d" % (min(i, j), max(i, j)), real=True))
    Ginv = lambda w: w * sp.eye(2) + As - Sig(w)                                 # G(z)^-1 by definition
    anchor_A = (Ginv(z0) - z0 * sp.eye(2) + Sig(z0) - As).applyfunc(sp.expand) == sp.zeros(2, 2)
    anchor_G = (Ginv(z) - (Ginv(z0) + (z - z0) * sp.eye(2) + Sig(z0) - Sig(z))).applyfunc(sp.expand) == sp.zeros(2, 2)
    Bn, Cn, An = sp.Matrix([[1, 2], [-1, 3]]), sp.Matrix([[5, 1], [1, 7]]), sp.Matrix([[2, sp.Rational(1, 2)], [sp.Rational(1, 2), 3]])
    Sn = lambda w: Bn * (w * sp.eye(2) + Cn).inv() * Bn.T
    Gn = lambda w: (w * sp.eye(2) + An - Sn(w)).inv()
    anchor_inst = (Gn(1).inv() - sp.eye(2) + Sn(1) == An
                   and (Gn(1).inv() + 2 * sp.eye(2) + Sn(1) - Sn(3)).inv() == Gn(3))
    # the root-site instance
    B, C, Bm, vis, hid, lam, sigma, resolvent_columns = _bind_rootsite()
    S1, S4, S16 = sigma(1), sigma(4), sigma(16)
    W1, cw = resolvent_columns(1)
    W4, c4 = resolvent_columns(4)
    W16, c16 = resolvent_columns(16)
    e1, e4 = (S1 - S4) / 3, (S4 - S16) / 12
    BBt = Bm * Bm.T
    offrow = max(sum(-int(C[i, j]) for j in range(225) if j != i) for i in range(225))
    diag = {int(C[i, i]) for i in range(225)}
    psd = [_bind_psd(M) for M in (S4, BBt / 4 - S4, S16, BBt / 16 - S16)]
    return {
        "P01 symbolically: on a generic block (visible 2, hidden 2, B generic, C symmetric) with Sigma(z) = B (z + C)^-1 "
        "B^T and e(z) = [Sigma(z) - Sigma(4z)]/(3z), Sigma(z) - 3z sum_(j < N) 4^j e(4^j z) = Sigma(4^N z) identically in "
        "z for N = 1, 2, 3 (the sum telescopes)":
            all(tails),
        "on the root-site instance (master_response: the 15 bond atoms visible, the 225 other roots hidden, B = "
        "(H_R)_(vis, hid) with entries in {0, -1}, C = (H_R)_(hid, hid) with diagonal 240 and off-diagonal row sums at "
        "most 56 < 240, so C > 0 by Gershgorin; the five sector eigenvalues of B_R are 56, 28, 8, -2, -4) the exact "
        "rational Sigma(1), Sigma(4), Sigma(16) from the block trick are each certified by (w + C) W_w = B^T and "
        "Sigma(w) = B W_w at w = 1, 4, 16 (master_response's own check, replayed), and with e(1) = [Sigma(1) - "
        "Sigma(4)]/3 and e(4) = [Sigma(4) - Sigma(16)]/12 read off them, Sigma(1) - 3 e(1) = Sigma(4) and Sigma(1) - 3 "
        "[e(1) + 4 e(4)] = Sigma(16) (z = 1, N = 1, 2): the content is the three certified values, the subtraction "
        "being P01's identity":
            set(int(v) for v in B.ravel()) <= {0, -1} and diag == {240} and offrow <= 56 < 240
            and lam == [56, 28, 8, -2, -4] and S1 - 3 * e1 == S4 and S1 - 3 * (e1 + 4 * e4) == S16
            and cw and c4 and c16 and S1 == Bm * W1 and S4 == Bm * W4 and S16 == Bm * W16,
        "the Loewner tail bound by exact inertia: Sigma(4) >= 0, B B^T/4 - Sigma(4) >= 0, Sigma(16) >= 0 and B B^T/16 - "
        "Sigma(16) >= 0, each with 15 positive pivots and no zero pivot in exact symmetric elimination, so 0 < Sigma(4^N "
        "z) < B B^T/(4^N z) at z = 1, N = 1, 2 (B has rank 15 and C > 0)":
            psd == [(15, 0)] * 4 and BBt.rank() == 15,
        "the load identity symbolically: G_L(z)^-1 - G_0(z)^-1 = L for G_L = (z + K + L)^-1 on a generic symmetric 2 x "
        "2 K and L (master_response's S_K^-1 - S_H^-1 = V, cited by tdc_frequency)":
            load,
        "the measured secant: with the hidden block in physical units (B/rho, C/rho^2) E_meas(s) = rho^2 e((rho s)^2), "
        "P01's form; with the whole generator scaled, (B/rho^2, C/rho^2), it is e((rho s)^2), the crossover note's "
        "form; either way E_meas depends on rho, and reconstructing Sigma_N at z = (rho s)^2 needs rho from "
        "bind_time_map first: time before dynamics":
            E1 and E2 and needs_rho,
        "the scale-free form (the three-route note, 6 Nov 08:44): with the generator K/rho^2, E_phys(s) = e((rho s)^2), "
        "and at x = s/s* with rho s* = sqrt(z*) the dyadic sum 3 z* x^2 sum_(n < N) 4^n E_phys(2^n s* x) equals "
        "Sigma(z* x^2) - Sigma(4^N z* x^2) with rho cancelling (symbolic, N = 2, generic block): the memory's shape in "
        "model units is read from rate ratios s/s* alone once the crossover s* is found, before any second is assigned; "
        "the absolute Sigma_phys(s) = rho^-2 Sigma((rho s)^2) still needs rho":
            sf_ok and sf_free,
        "the one-anchor recovery (the three-route txt): for G(z) = (z + A - Sigma(z))^-1 with A symmetric, one full "
        "G(z0) fixes A = G(z0)^-1 - z0 I + Sigma(z0), and then G(z)^-1 = G(z0)^-1 + (z - z0) I + Sigma(z0) - Sigma(z) "
        "for every z (symbolic on the generic block): the full secant curve and one anchor give the compressed Green "
        "function on the visible block, not the hidden realization (the note's own caveat; the model's comparator "
        "non-uniqueness is notes_1418's last diagonal 200 or 210); exact on a "
        "rational instance (B = [[1, 2], [-1, 3]], C = [[5, 1], [1, 7]] > 0, A = [[2, 1/2], [1/2, 3]]) at z0 = 1, z = 3":
            anchor_A and anchor_G and anchor_inst,
    }


def bind_selections():
    """DYN_BIND's content as a checked table: the dynamics is the declared native action (the 'source' dot, q'' + 4q =
    0 on ker M + ker M, native.run), and its completion family K_theta = H + theta (eps + J V J^T) = (1 - theta) H +
    theta K19 (flower_homotopy) carries named selections, each fixed or recorded by a model function. The gates stay:
    the solution installs maps (bind_time_map, bind_time_units, bind_dynamics_dyadic), not data."""
    table = [
        ("theta", "flower_homotopy", "the convex family K_theta = (1 - theta) H + theta K19 at the note's five theta"),
        ("eps", "schur_zero_mode", "eps = 1 on the root-site instance (master_response's regulator)"),
        ("alpha", "schur_zero_mode", "the admissible S_alpha at alpha = 1 (chiral_closures' F19 = D19^2 symbolic in alpha)"),
        ("the mark", "mgm_marks", "the twelve Golden marks, their zero lines and their average"),
        ("J", "schur_zero_mode", "J19 into the 45-channel section (master_readout's J15 and the dark four)"),
        ("W_p", "literal_port", "the owner's W_p in boundary order (native_matrices_input.json, 73e07429...)"),
        ("the adapter", "literal_port", "the reconstructed port up to a commutant element (parent_readers' marked adapter)"),
        ("iota", "canon_flower_pullback", "the cycles' inclusion into the edge block of R^19, an isometry on L6"),
        ("the parity", "zero_pole_parity", "the D10 parity of the zero-mode line against the golden time line"),
        ("the readout", "master_readout", "the 45 channels and D45 = (2117, 967^8, 389^26, 127^6, 83^4)"),
    ]
    import inspect
    names = {f for _, f, _ in table} | {"parent_readers", "master_response", "native"}
    g = globals()
    H, V, eps, th = sp.symbols("H V epsilon theta")
    return {
        "the dynamics is the declared native action: the 'source' dot reads q'' + 4q = 0 on ker M + ker M and "
        "native.run(simulate, steps, dt) exists; the completion family K_theta = H + theta (eps + J V J^T) is "
        "flower_homotopy's (1 - theta) H + theta K19 with K19 = H + eps + J V J^T (symbolic identity)":
            DOTS["source"][1] == "q'' + 4q = 0 on ker M + ker M" and callable(getattr(native, "run", None))
            and list(inspect.signature(native.run).parameters) == ["simulate", "steps", "dt"]
            and sp.expand(H + th * (eps + V) - ((1 - th) * H + th * (H + eps + V))) == 0,
        "the selection table: theta (flower_homotopy), eps and alpha and J (schur_zero_mode), the mark (mgm_marks), "
        "W_p and the adapter (literal_port, parent_readers), iota (canon_flower_pullback), the parity "
        "(zero_pole_parity), the readout (master_readout): every named function exists in oes.dots and is callable":
            all(callable(g.get(n)) for n in names - {"native"}) and len(table) == 10,
        "the gates stay: gates.GATES['TIME_BIND'] == 'UNBOUND' and gates.GATES['DYN_BIND'] == 'NOT_INSTALLED'; the "
        "solution installs maps (bind_time_map, bind_time_units, bind_dynamics_dyadic), not data, and no physical "
        "datum exists in the model":
            gates.GATES["TIME_BIND"] == "UNBOUND" and gates.GATES["DYN_BIND"] == "NOT_INSTALLED"
            and all(callable(g.get(n)) for n in ("bind_time_map", "bind_time_units", "bind_dynamics_dyadic")),
    }


# ------------------------------------------------------------------- unified at all levels (30 Oct): golden, torus

def golden_cosine():
    """The golden companion is the tick's negative cosine: E8 is Z[phi]^4 with phi = -(g + g^-1)."""
    x = sp.Symbol("x")
    I8 = np.eye(8, dtype=np.int64)
    B2 = np.array([[1, 1], [1, 0]], dtype=np.int64)
    g = cyclotomic.clocks()["g"]
    RB = spine.frame()[5]
    eta = g + spine.inverse(g)
    X = -eta
    Phi = I8 + g + spine.mpow(g, 4)
    char = lambda M: sp.Poly(sp.Matrix(M.tolist()).charpoly(x).as_expr(), x)
    cols = lambda idx: np.array([v for i in idx for v in (X @ RB[i], RB[i])], dtype=np.int64).T
    unimodular = lambda M: abs(round(np.linalg.det(M.astype(float)))) == 1
    rank = lambda M: np.linalg.matrix_rank(M.astype(float))
    idx = next(((a, b, c, d) for a in range(240) for b in range(a + 1, 240) if rank(cols((a, b))) == 4
                for c in range(b + 1, 240) if rank(cols((a, b, c))) == 6
                for d in range(c + 1, 240) if unimodular(cols((a, b, c, d)))), None)
    basis = cols(idx)
    binv = np.rint(np.linalg.inv(basis.astype(float))).astype(np.int64)
    Pg = [spine.mpow(g, j) for j in range(4)]
    x0 = RB[0]
    span = lambda y: np.array([Pg[j] @ x0 for j in range(4)] + [Pg[j] @ y for j in range(4)], dtype=np.int64).T
    pairs = [i for i, y in enumerate(RB) if unimodular(span(y))]
    _, lines = cyclotomic.residue()
    line0 = next(L for L in lines if cyclotomic.point(x0) in L)
    on_line = [i for i, y in enumerate(RB) if cyclotomic.point(y) in line0]
    return {
        "the tick's cosine g + g^-1 has minimal polynomial x^2 + x - 1 (the polynomial of 2 cos 72 degrees), so its "
        "negative X = -(g + g^-1) satisfies X^2 = X + I with characteristic polynomial (x^2 - x - 1)^4: the golden "
        "companion's polynomial, each of phi and 1 - phi with multiplicity 4; X = I - Phi for layer 27's "
        "Phi = 1 + g + g^4":
            not (eta @ eta + eta - I8).any() and (eta - eta[0, 0] * I8).any()
            and char(X) == sp.Poly((x ** 2 - x - 1) ** 4, x) and not (X @ X - X - I8).any()
            and np.array_equal(X, I8 - Phi),
        "E8 has a Z-basis of four roots x_i and their images X x_i, ordered (X x_i, x_i), in which X is four blocks "
        "B = [[1, 1], [1, 0]]: "
        "E8 is a free module of rank 4 over Z[phi] = Z[X], the golden companion acting on all of the lattice":
            idx is not None and np.array_equal(basis @ binv, I8)
            and np.array_equal(binv @ X @ basis, np.kron(np.eye(4, dtype=np.int64), B2)),
        "Z[g] = Z[zeta5] makes E8 a free module of rank 2: the Z-span of g^j x0 for one root x0 has rank 4, and "
        "{g^j x0, g^j y} is a Z-basis for 200 of the roots y, exactly those off the A4 + A4 of x0's residue line":
            rank(span(x0)[:, :4]) == 4 and len(pairs) == 200
            and sorted(set(range(240)) - set(pairs)) == on_line and len(on_line) == 40,
    }


def golden_galois():
    """The day conjugates the golden companion: G120 realizes Gal(Q(sqrt5)/Q) on the tick's cosine."""
    I8 = np.eye(8, dtype=np.int64)
    B2 = np.array([[1, 1], [1, 0]], dtype=np.int64)
    k = cyclotomic.clocks()
    g, d, c = k["g"], k["day"], k["c"]
    inv = spine.inverse
    X = -(g + inv(g))
    G = primes._matrix_group([c, d])
    conj = lambda W: W @ X @ inv(W)
    fix = [W for W in G if np.array_equal(conj(W), X)]
    flip = [W for W in G if np.array_equal(conj(W), I8 - X)]
    H = primes._matrix_group([g, d @ d])
    key = lambda M: tuple(M.flatten().tolist())
    J = np.array([[0, 1], [-1, 0]], dtype=np.int64)
    return {
        "the day conjugates the tick to its square, d g d^-1 = g^2, so it carries the cosine g + g^-1 to "
        "g^2 + g^-2 = -(g + g^-1) - I and X = -(g + g^-1) to I - X: the day acts on Z[phi] = Z[X] as the Galois "
        "conjugation phi -> 1 - phi = -1/phi":
            np.array_equal(d @ g @ inv(d), spine.mpow(g, 2))
            and np.array_equal(d @ (g + inv(g)) @ inv(d), -(g + inv(g)) - I8)
            and np.array_equal(d @ X @ inv(d), I8 - X),
        "c' commutes with X, so G120 = <c', d> acts on Z[X] through Gal(Q(sqrt5)/Q) = Z/2: 60 elements fix X and 60 "
        "carry it to I - X, and the kernel is <g, d^2>, the day's square conjugating the tick to its inverse":
            np.array_equal(c @ X @ inv(c), X) and len(G) == 120 and len(fix) == 60 and len(flip) == 60
            and {key(W) for W in fix} == {key(W) for W in H} and len(H) == 60
            and np.array_equal(d @ d @ g @ inv(d @ d), inv(g)),
        "the two roots of x^2 - x - 1 in the ring Z[X], X and I - X = Phi = I + g + g^4, are the two embeddings of Z[phi] "
        "into Z[X] (End(E8) has further roots, the conjugates s_i X s_i), and the quarter turn J = [[0, 1], [-1, 0]] in "
        "SL(2,Z) conjugates B to I - B: the embedding into Z[X] is unique up to the day":
            np.array_equal(J @ B2 @ np.rint(np.linalg.inv(J)).astype(np.int64), np.eye(2, dtype=np.int64) - B2)
            and round(np.linalg.det(J.astype(float))) == 1 and not ((I8 - X) @ (I8 - X) - (I8 - X) - I8).any()
            and np.array_equal(I8 - X, I8 + g + spine.mpow(g, 4)),
    }


def regular_cosines():
    """The cosines of the thirteen regular clocks, and which of them carry the golden companion."""
    x = sp.Symbol("x")
    I8 = np.eye(8, dtype=np.int64)
    g = cyclotomic.clocks()["g"]
    X = -(g + spine.inverse(g))
    Xv = sp.Matrix(X.flatten().tolist())
    reg = primes.regular()
    psi, charpolys, inside = {}, {}, {}
    for n, w in reg.items():
        eta = w + spine.inverse(w)
        psi[n] = sp.Poly(sp.minimal_polynomial(2 * sp.cos(2 * sp.pi / n), x), x)
        charpolys[n] = sp.Poly(sp.Matrix(eta.tolist()).charpoly(x).as_expr(), x) == psi[n] ** (8 // psi[n].degree())
        powers = [I8]
        for _ in range(psi[n].degree() - 1):
            powers.append(powers[-1] @ eta)
        sol = sp.linsolve((sp.Matrix([p.flatten().tolist() for p in powers]).T, Xv))
        inside[n] = None if sol == sp.EmptySet else tuple(next(iter(sol)))
    found = {n: s for n, s in inside.items() if s is not None}
    v, w10 = reg[20], reg[10]
    return {
        "the cosine w + w^-1 of the regular clock of order d has characteristic polynomial Psi_d^(8/deg Psi_d), Psi_d "
        "the minimal polynomial of 2 cos(2 pi/d): degree phi(d)/2 for d >= 3, so (x -+ 2)^8, (x + 1)^8, x^8, "
        "(x^2 + x - 1)^4, (x - 1)^8, (x^2 - 2)^4, (x^2 - x - 1)^4, (x^2 - 3)^4 and four quartics squared for "
        "d = 15, 20, 24, 30":
            all(charpolys.values()) and all(psi[n].degree() == primes._phi(n) // 2 for n in psi if n >= 3)
            and psi[5].as_expr() == x ** 2 + x - 1 and psi[10].as_expr() == x ** 2 - x - 1
            and psi[20].as_expr() == x ** 4 - 5 * x ** 2 + 5 and psi[24].as_expr() == x ** 4 - 4 * x ** 2 + 1,
        "the golden companion's polynomial x^2 - x - 1 is Psi_10 = Psi_5(-x): the regular clock of order 10, "
        "c'^3 = -g^3, has cosine Phi = 1 + g + g^4 and the tick has negative cosine X = 1 - Phi; the golden clock's "
        "cosine squares to Phi + 2, (v + v^-1)^2 - 2 = v^2 + v^-2 = Phi, as 2 cos 18 degrees squared is "
        "(5 + sqrt5)/2":
            np.array_equal(w10, -spine.mpow(g, 3)) and np.array_equal(w10 + spine.inverse(w10), I8 - X)
            and np.array_equal(spine.mpow(v, 2), w10)
            and np.array_equal(np.linalg.matrix_power(v + spine.inverse(v), 2) - 2 * I8, I8 - X),
        "X lies in the cosine ring Z[w + w^-1] exactly for the five regular orders divisible by 5, with integer "
        "coefficients: -eta (5), 1 - eta (10), 3 eta - eta^3 (15), 3 - eta^2 (20) and 1 + 3 eta - eta^3 (30); for "
        "the eight others it is not even in Q[w + w^-1], since Q(sqrt5) lies in Q(zeta_d) only when 5 | d":
            sorted(found) == [5, 10, 15, 20, 30]
            and found == {5: (0, -1), 10: (1, -1), 15: (0, 3, 0, -1), 20: (3, 0, -1, 0), 30: (1, 3, 0, -1)}
            and all(inside[n] is None for n in inside if n % 5),
    }


def torus_places():
    """The nine-torus at the four places: six of its nine squared frequencies are the band at the fixed momenta of the
    three prime clocks and at the principal circle's critical steps; the other three are at none of them."""
    B, Binv, C, Cinv, R, RB = spine.frame()
    k = cyclotomic.clocks()
    band = lambda x: 240 - np.cos(2 * np.pi * (R @ x)).sum()
    grad = lambda x: np.linalg.norm((np.sin(2 * np.pi * (R @ x))[:, None] * R).sum(axis=0))
    read = lambda xs: Counter((handover.stabiliser(R, x)[0], int(round(band(x)))) for x in xs if grad(x) < 1e-9)
    fam = {t: f for (_, t), f in _census().items()}
    eps = sorted({240 - v for v in _critical_values()} - {0})
    # on the line x = s omega_i the band is 240 - P_i(cos 2 pi s), P_i from the root counts on node i; the line's
    # stabilizer has rank 7, so the gradient lies along omega_i and the line's critical points are the band's
    c = sp.symbols("c")
    marks = [2, 3, 4, 6, 5, 4, 3, 2]
    P = [sum(m * sp.chebyshevt(abs(j), c) for j, m in Counter(int(v) for v in RB[:, i]).items()) for i in range(8)]
    vertex = {handover.stabiliser(R, B @ Cinv[:, i] / marks[i])[0]: 240 - sp.expand(P[i].subs(c, sp.cos(2 * sp.pi / marks[i])))
              for i in range(8)}
    turn = lambda i, r: float(sp.acos(r) / (2 * sp.pi)) * (B @ Cinv[:, i])
    off = {(i, r): (handover.stabiliser(R, turn(i, r))[0], 240 - P[i].subs(c, r), grad(turn(i, r)) < 1e-9)
           for i in (1, 2) for r in sp.roots(sp.Poly(sp.diff(P[i], c), c)) if r not in (0, sp.Rational(-1, 2))}
    torsion = {0, sp.Rational(1, 2), sp.Rational(-1, 2), sp.cos(2 * sp.pi / 5), sp.cos(4 * sp.pi / 5)}
    others = {(i, r) for i in range(8) for r in sp.roots(sp.Poly(sp.diff(P[i], c), c)) if abs(r) < 1 and r not in torsion}
    exact = {**vertex, **{t: e for t, e, _ in off.values()}, "E8": 0}
